const nextAllocationRevision = `-- name: NextAllocationRevision :one
SELECT id, scheme_id, effective_at, config FROM allocation_revisions WHERE scheme_id=? AND effective_at>? ORDER BY effective_at LIMIT 1
`

type NextAllocationRevisionParams struct {
	SchemeID    int64
	EffectiveAt int64
}

func (q *Queries) NextAllocationRevision(ctx context.Context, arg NextAllocationRevisionParams) (AllocationRevision, error) {
	row := q.db.QueryRowContext(ctx, nextAllocationRevision, arg.SchemeID, arg.EffectiveAt)
	var i AllocationRevision
	err := row.Scan(
		&i.ID,
		&i.SchemeID,
		&i.EffectiveAt,
		&i.Config,
	)
	return i, err
}

const pruneAllocations = `-- name: PruneAllocations :execrows
DELETE FROM allocation_entries WHERE rowid IN (
 SELECT old.rowid FROM allocation_entries old WHERE old.state='settled' AND old.reset_at<?1 LIMIT 500
)
`

func (q *Queries) PruneAllocations(ctx context.Context, before int64) (int64, error) {
	result, err := q.db.ExecContext(ctx, pruneAllocations, before)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const recoverAllocationEntries = `-- name: RecoverAllocationEntries :exec
UPDATE allocation_entries SET state='pending' WHERE state='active' AND EXISTS(
SELECT 1 FROM allocation_schemes s JOIN account_groups g ON g.id=s.group_id
WHERE s.id=allocation_entries.scheme_id AND g.tenant_id=?1)
`

func (q *Queries) RecoverAllocationEntries(ctx context.Context, tenantID int64) error {
	_, err := q.db.ExecContext(ctx, recoverAllocationEntries, tenantID)
	return err
}

